#!/usr/bin/env python3
"""Generates src/main/java/org/hl7/fhir/jekyll/rouge/LexerData.java from meta.json (dump_meta.rb)."""
import json, os
here = os.path.dirname(os.path.abspath(__file__))
d = json.load(open(os.path.join(here, 'meta.json')))
def jstr(s): return json.dumps(s, ensure_ascii=False)
def jarr(a): return 'new String[] {' + ', '.join(jstr(x) for x in a) + '}'
out = ['package org.hl7.fhir.jekyll.rouge;', '',
       '/** Generated by jekyll/tests/rouge/gen_lexer_data.py from Rouge ' + d['version'] + ' (dump_meta.rb): every lexer class',
       ' * in Lexer.all order (class, tag, aliases, filenames, mimetypes, detectable?, title) and the registry. */',
       'final class LexerData {', '  private LexerData() {}', '',
       '  static final Object[][] ALL = {']
for a in d['all']:
    out.append('    {%s, %s, %s, %s, %s, %s, %s},' % (jstr(a['class']), jstr(a['tag']), jarr(a['aliases']), jarr(a['filenames']),
               jarr(a['mimetypes']), 'true' if a['detectable'] else 'false', jstr(a['title'])))
out.append('  };')
out.append('')
out.append('  /** Rouge::Lexer.registry: name -> class, in insertion order. */')
out.append('  static final String[][] REGISTRY = {')
line = '   '
for k, v in d['registry']:
    item = ' {%s, %s},' % (jstr(k), jstr(v))
    if len(line) + len(item) > 110:
        out.append(line); line = '   '
    line += item
out.append(line)
out.append('  };')
out.append('}')
open(os.path.join(here, '../../src/main/java/org/hl7/fhir/jekyll/rouge/LexerData.java'), 'w').write('\n'.join(out) + '\n')
